import { renderHome, renderSiteFooter } from './home.js';
let D;
const main=document.querySelector('#main');
const dialog=document.querySelector('#dialog');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nl=v=>esc(v).replace(/\n/g,'<br>');
const safeUrl=v=>{try{const u=new URL(v,location.origin);return ['http:','https:','mailto:'].includes(u.protocol)&&v?u.href:'';}catch{return '';}};
const asset=v=>{const u=safeUrl(v);return u&&!u.startsWith('mailto:')?u:'';};
const route=(type,slug)=>`/${type}/${slug}`;
const member=id=>D.members.find(m=>m.slug===id);
const project=id=>D.projects.find(p=>p.slug===id);
const course=id=>D.courses.find(c=>c.slug===id);
const lab=id=>D.labs.find(l=>l.slug===id);
const paper=id=>D.publications.find(p=>p.id===id);
const icons={arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',search:'m21 21-5.5-5.5M18 10.5a7.5 7.5 0 1 1-15 0 7.5 7.5 0 0 1 15 0',menu:'M4 6h16M4 12h16M4 18h16',close:'m6 6 12 12M6 18 18 6',bolt:'m13 2-9 12h7l-1 8 10-12h-7l1-8',atom:'M12 11v2m-9-1c0-2.5 4-4.5 9-4.5s9 2 9 4.5-4 4.5-9 4.5-9-2-9-4.5M7.5 4.2c2.2-1.2 5.9 1.2 8.4 5.5s2.6 8.7.5 10-5.9-1.2-8.4-5.5-2.6-8.7-.5-10M16.5 4.2c2.2 1.3 2 5.7-.5 10s-6.2 6.7-8.4 5.5-2-5.7.5-10 6.2-6.7 8.4-5.5',code:'m8 5-6 7 6 7m8-14 6 7-6 7M14 3l-4 18',shield:'m12 2 8 3v7c0 5-8 10-8 10S4 17 4 12V5l8-3m-4 10 3 3 5-6',layers:'m12 3 10 6-10 6L2 9l10-6M2 13l10 6 10-6M2 17l10 6 10-6',book:'M12 5v16M3 3c4 0 7 1 9 3 2-2 5-3 9-3v15c-4 0-7 1-9 3-2-2-5-3-9-3V3',mail:'M3 5h18v14H3V5m0 1 9 7 9-7',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18',calendar:'M5 5h14v16H5V5m3-3v6m8-6v6M5 11h14',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0m-9-5v5l3 2',play:'m9 5 10 7-10 7V5',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',external:'M14 3h7v7m-1-6L10 14M10 3H3v18h18v-7',scholar:'m2 9 10-6 10 6-10 6L2 9m4 3v6l6 3 6-3v-6M22 9v9',linkedin:'M5 9v12M5 4v1M10 21V9h4v2c4-4 6 0 6 3v7m-6-9v9',github:'M9 21v-3c-4 1-4-2-6-2m12 5v-4c3-1 5-2 5-6 0-2-1-3-2-4 0-1 0-3-1-4l-4 2h-3L6 3C5 4 5 6 5 7c-1 1-2 2-2 4 0 4 2 5 6 6',youtube:'M21 7v10c-5 2-13 2-18 0V7c5-2 13-2 18 0m-11 2 6 3-6 3V9',facebook:'M14 22V12h4l1-4h-5V5c0-2 3-2 5-2V0h-5c-4 0-5 3-5 5v3H6v4h3v10',check:'m5 12 4 4L20 5',compass:'m15 9-2 5-5 2 2-5 5-2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0m-5 0a4 4 0 1 1-8 0 4 4 0 0 1 8 0m-4-9v18M3 12h18',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7'};
function icon(name,size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.external}"/></svg>`;}
function initializeAppearance(){if(document.documentElement)document.documentElement.dataset.theme='light';document.querySelector('meta[name="theme-color"]')?.setAttribute('content','#ffffff');try{localStorage.removeItem('ofl-theme');}catch{}}
function registrationUrl(value){try{if(typeof value!=='string'||!value.trim())return '';const url=new URL(value.trim());return url.protocol==='https:'&&!url.username&&!url.password?url.href:'';}catch{return '';}}
function registrationButton(){const url=registrationUrl(D.organization.registrationUrl);return url?`<a class="btn header-register" href="${esc(url)}">Register ${icon('external',14)}</a>`:`<button class="btn header-register" type="button" data-action="registration-info">Register ${icon('arrow',14)}</button>`;}
function openRegistrationNotice(){showDialog('Registration opens soon',`<p class="dialog-description">Registration is not open yet. Please check back later or contact the lab for enrollment information.</p><div class="buttons">${btn('Contact the lab','/contact')}<button class="btn secondary" data-action="close-dialog">Close</button></div>`);}
function logo(){return `<svg width="39" height="42" viewBox="0 0 44 48" fill="none" aria-hidden="true"><path d="m22 3 18 10v22L22 45 4 35V13L22 3Z" stroke="currentColor" stroke-width="1.6"/><path d="m4 13 18 11 18-11M22 24v21M4 35l18-11 18 11M22 3v21" stroke="currentColor" stroke-width="1.1"/><circle cx="22" cy="24" r="4" fill="currentColor"/><circle cx="22" cy="3" r="2.5" fill="currentColor"/><circle cx="40" cy="35" r="2.5" fill="currentColor"/><circle cx="4" cy="35" r="2.5" fill="currentColor"/></svg>`;}
const brand=()=>`<a class="brand" href="/" aria-label="${esc(D.organization.name)} home">${logo()}<span class="brand-name">${esc(D.organization.name)}<small>Virtual research organization</small></span></a>`;
const arrowLink=(label,url,cls='')=>`<a class="text-link ${cls}" href="${esc(url)}">${esc(label)} ${icon('arrow',16)}</a>`;
const btn=(label,url,cls='')=>`<a class="btn ${cls}" href="${esc(url)}">${esc(label)}${icon('arrow',16)}</a>`;
const external=(label,url,ic='external',cls='')=>safeUrl(url)?`<a class="${cls}" href="${esc(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${ic?icon(ic,14):''}${esc(label)}</a>`:`<span class="${cls} disabled" title="Link coming soon">${ic?icon(ic,14):''}${esc(label)}</span>`;
function avatar(m,size=''){return `<span class="avatar ${esc(m.color)} ${size}" aria-hidden="true">${asset(m.image)?`<img src="${esc(asset(m.image))}" alt="" loading="lazy">`:esc(m.initials)}</span>`;}
function dateParts(e){const d=new Date(e.date);return {day:new Intl.DateTimeFormat('en',{day:'2-digit',timeZone:e.timezone}).format(d),month:new Intl.DateTimeFormat('en',{month:'short',timeZone:e.timezone}).format(d),date:new Intl.DateTimeFormat('en',{day:'numeric',month:'long',year:'numeric',timeZone:e.timezone}).format(d),time:new Intl.DateTimeFormat('en',{hour:'numeric',minute:'2-digit',hour12:true,timeZone:e.timezone}).format(d)};}
const shortDate=v=>new Intl.DateTimeFormat('en',{day:'2-digit',month:'short',year:'numeric',timeZone:'Asia/Dhaka'}).format(new Date(v));
const futureEvents=()=>D.events.filter(e=>new Date(e.end)>new Date()).sort((a,b)=>new Date(a.date)-new Date(b.date));
function header(){const page=location.pathname.split('/')[1];const active=n=>n.url==='/'?!page:page===n.url.slice(1);document.querySelector('#header').innerHTML=`<span class="scroll-progress" aria-hidden="true"></span><div class="container nav">${brand()}<nav class="nav-links" id="primary-nav" aria-label="Main navigation">${D.navigation.map(n=>`<a href="${esc(n.url)}" class="nav-link ${active(n)?'active':''}" ${active(n)?'aria-current="page"':''}>${esc(n.label)}</a>`).join('')}</nav><div class="nav-actions"><button class="icon-btn" data-action="search" aria-label="Search the site" title="Search the site">${icon('search',18)}</button><button class="icon-btn menu-btn" data-action="menu" aria-label="Toggle navigation" aria-controls="primary-nav" aria-expanded="false">${icon('menu',20)}</button>${registrationButton()}</div></div>`;}
function footer(){document.querySelector('#footer').innerHTML=renderSiteFooter({data:D,esc,safeUrl,icon,brand});}
function projectArt(p){if(asset(p.image))return `<img src="${esc(asset(p.image))}" alt="${esc(p.title)}" loading="lazy">`;const paths={wave:'M0 90c20 0 15-30 35-30s20 75 40 75 25-110 45-110 25 100 45 100 20-60 40-60 25 35 45 35 25-30 50-30',orbit:'M90 28c55-35 110 5 75 65S70 150 95 90 185 40 190 100',network:'M55 40 150 35 240 70 205 140 115 130 55 40 240 70 115 130 150 35 205 140',bars:'M60 130V85h20v45m25 0V45h20v85m25 0V65h20v65m25 0V25h20v105'};return `<svg viewBox="0 0 300 170" fill="none" aria-hidden="true"><defs><pattern id="dots-${esc(p.slug)}" width="17" height="17" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".65" fill="currentColor" opacity=".2"/></pattern></defs><rect width="300" height="170" fill="url(#dots-${esc(p.slug)})"/><g stroke="currentColor" opacity=".35"><path d="M25 145h250M25 25v120" stroke-dasharray="3 5"/><circle cx="150" cy="85" r="60" stroke-dasharray="3 6" opacity=".4"/></g><path d="${paths[p.art]||paths.wave}" stroke="currentColor" stroke-width="1.4" opacity=".65"/>${p.art==='orbit'?'<ellipse cx="150" cy="85" rx="83" ry="30" stroke="currentColor" opacity=".4" transform="rotate(-25 150 85)"/><circle cx="150" cy="85" r="8" fill="currentColor" opacity=".4"/>':p.art==='network'?[[55,40],[150,35],[240,70],[205,140],[115,130]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="5" fill="currentColor"/>`).join(''):''}</svg>`;}
function labArt(l){return `<div class="lab-art" aria-hidden="true">${l.icon==='atom'?'<svg viewBox="0 0 180 200" fill="none"><g stroke="currentColor" stroke-width="1"><ellipse cx="92" cy="100" rx="72" ry="26"/><ellipse cx="92" cy="100" rx="72" ry="26" transform="rotate(60 92 100)"/><ellipse cx="92" cy="100" rx="72" ry="26" transform="rotate(120 92 100)"/><circle cx="92" cy="100" r="9" fill="currentColor"/><circle cx="150" cy="82" r="5" fill="currentColor"/><circle cx="67" cy="45" r="4" fill="currentColor"/><circle cx="72" cy="157" r="4" fill="currentColor"/></g></svg>':'<svg viewBox="0 0 180 200" fill="none"><g stroke="currentColor" stroke-width="1.1"><path d="m95 25-35 145m35-145 35 145M77 100h36M70 130h50M80 85h30M68 67h54M55 100h80M63 67v22m65-22v22M51 100v23m88-23v23M70 130l43-30M77 100l43 30M80 85l33-18M77 67l33 18"/><path d="M20 178c30-10 55-10 85 0s45 10 70 0M20 188h155" opacity=".4"/><circle cx="35" cy="45" r="18" stroke-dasharray="3 5"/><path d="M17 45h36M35 27v36" opacity=".4"/></g></svg>'}</div>`;}
function labCard(l){return `<article class="lab-card ${esc(l.color)}"><div class="lab-card-content"><div class="eyebrow">LAB ${esc(l.number)} / ${esc(l.category)}</div><h3>${nl(l.shortTitle)}</h3><p>${esc(l.summary)}</p>${arrowLink('Explore the lab',route('labs',l.slug))}<div class="resource-note">${icon('book',13)}Class recordings & research papers</div></div>${asset(l.image)?`<img class="lab-art" src="${esc(asset(l.image))}" alt="" loading="lazy">`:labArt(l)}</article>`;}
function projectCard(p){return `<article class="project-card"><a href="${route('projects',p.slug)}" class="project-art ${esc(p.color)}" tabindex="-1" aria-hidden="true">${projectArt(p)}${p.funded?'<span class="badge">FUNDED RESEARCH</span>':''}</a><div class="project-body"><div class="eyebrow">${esc(p.category)}</div><h3><a href="${route('projects',p.slug)}">${esc(p.title)}</a></h3><p>${esc(p.summary)}</p><a class="text-link" href="${route('projects',p.slug)}"><span>Explore project <span class="project-status">/ ${esc(p.status)}</span></span>${icon('arrow',16)}</a></div></article>`;}
function courseCard(c,full=false){return `<article class="course-card"><div class="course-icon ${esc(c.color)}">${icon(c.icon,21)}</div><div class="eyebrow">${esc(c.category)}</div><h3><a href="${route('courses',c.slug)}">${esc(c.title)}</a></h3>${full?`<p>${esc(c.summary)}</p>`:''}<div class="course-meta"><span>${esc(c.level)}</span><span>·</span><span>${esc(c.duration)}</span></div><a class="course-foot" href="${route('courses',c.slug)}"><span>${esc(c.status)}</span>${icon('arrow',15)}<span class="sr-only">View ${esc(c.title)}</span></a></article>`;}
function memberCard(m){return `<article class="member-card"><div class="member-top">${avatar(m)}<div><h3><a href="${route('team',m.slug)}">${esc(m.name)}</a></h3><div class="designation">${esc(m.designation)}</div></div></div><p>${esc(m.bio)}</p><div class="member-bottom">${arrowLink('View portfolio',route('team',m.slug))}<div class="member-socials">${external('',m.scholar,'scholar','social-icon') .replace('class="social-icon"','class="social-icon" aria-label="Google Scholar"').replace('class="social-icon disabled"','class="social-icon disabled" aria-label="Google Scholar link coming soon"')}${safeUrl(m.linkedin)?`<a class="social-icon" href="${esc(safeUrl(m.linkedin))}" target="_blank" rel="noopener noreferrer" aria-label="LinkedIn">${icon('linkedin',14)}</a>`:''}<a class="social-icon" href="mailto:${esc(m.email)}" aria-label="Email ${esc(m.name)}">${icon('mail',14)}</a></div></div></article>`;}
function miniMember(m){return m?`<a class="mini-member" href="${route('team',m.slug)}">${avatar(m)}<span><b>${esc(m.name)}</b><span>${esc(m.designation)}</span></span><span class="arrow">${icon('arrow',16)}</span></a>`:'';}
function sectionHead(eyebrow,title,label,url,description=''){return `<div class="section-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h2>${nl(title)}</h2>${description?`<p>${esc(description)}</p>`:''}</div>${label?arrowLink(label,url):''}</div>`;}
function dateBox(e){const d=dateParts(e);return `<div class="event-date"><span>${d.month}</span><strong>${d.day}</strong></div>`;}
function eventBanner(e){if(!e)return '';const m=member(e.speaker),d=dateParts(e);return `<div class="event-banner">${dateBox(e)}<div><div class="eyebrow">NEXT UP / ${esc(e.type)}</div><h3><a href="${route('events',e.slug)}">${esc(e.title)}</a></h3><p>${icon('clock',12)}${esc(d.time)} · ${esc(e.timezone)} <span>·</span> With ${esc(m?.name||'Our community')}</p></div>${btn('View & register',route('events',e.slug),'light')}</div>`;}
function home(){return renderHome({data:D,esc,asset,icon,route,dateParts,futureEvents,projectArt});}
function pageHero(eyebrow,title,description='',extra='',crumbs=[]){return `<section class="page-hero"><div class="container"><div class="breadcrumbs"><a href="/">Home</a>${crumbs.map(c=>`${icon('chevron',10)}${c.url?`<a href="${esc(c.url)}">${esc(c.label)}</a>`:`<span>${esc(c.label)}</span>`}`).join('')}</div><div class="eyebrow">${esc(eyebrow)}</div>${title?`<h1>${nl(title)}</h1>`:''}${description?`<p>${esc(description)}</p>`:''}${extra}</div></section>`;}
function about(){const a=D.about;return `${pageHero('OUR PURPOSE',a.title,a.intro,'',[{label:'About'}])}<section class="section container"><div class="grid-2">${a.pillars.map(p=>`<article class="pillar"><div class="course-icon mint">${icon(p.icon,22)}</div><h3>${esc(p.title)}</h3><p>${esc(p.text)}</p></article>`).join('')}</div></section><section class="section-sm lab-section"><div class="container intro" style="border:0;padding:15px 0"><div><div class="eyebrow">HOW WE GOT HERE</div><h2>Our history</h2><span class="badge" style="margin-top:22px">Established ${esc(D.organization.founded)}</span></div><div><p>${esc(a.story)}</p><p>${esc(a.storyMore)}</p>${arrowLink('Meet the people behind the lab','/team')}</div></div></section><section class="section container">${sectionHead('GROWING TOGETHER','Our academic connections','','','Spaces for future institutional partners and research collaborators.')}<div class="grid-3">${a.partners.map(p=>`<div class="partner">${asset(p.logo)?`<img src="${esc(asset(p.logo))}" alt="${esc(p.name)}">`:`<strong>${esc(p.name)}</strong>`}<p>${esc(p.detail)}</p></div>`).join('')}</div><div class="join-strip" style="margin-top:50px"><div><h2>Research collaboration</h2><p>We welcome conversations about research and collaboration.</p></div>${btn('Start a conversation','/contact')}</div></section>`;}
function team(){return `${pageHero('OUR RESEARCH COMMUNITY','Research Team','Meet the people who guide, build, and bring our virtual labs to life. Explore each portfolio to learn about their work.','',[{label:'Team'}])}<section class="section container"><div class="toolbar"><div class="filter-group">${D.teamGroups.map((g,i)=>`<a class="filter-btn" href="#group-${i}">${esc(g)}</a>`).join('')}</div><label><span class="sr-only">Filter by joining year</span><select class="select" data-filter="team-year"><option value="all">All joining years</option>${[...new Set(D.members.map(m=>m.joined))].sort((a,b)=>b-a).map(y=>`<option>${y}</option>`).join('')}</select></label><input type="search" id="team-search" data-filter="team-search" aria-label="Search team members" placeholder="Search a name or interest…"></div><div id="team-results">${teamResults()}</div></section>`;}
function teamResults(){const query=document.querySelector('#team-search')?.value.toLowerCase()||'',year=document.querySelector('[data-filter=team-year]')?.value||'all';const members=D.members.filter(m=>(year==='all'||String(m.joined)===year)&&[m.name,m.designation,...m.interests].join(' ').toLowerCase().includes(query));return members.length?D.teamGroups.map((g,i)=>{const ms=members.filter(m=>m.group===g);return ms.length?`<section class="team-section" id="group-${i}"><div class="group-title"><h2>${esc(g)}</h2><span>${String(ms.length).padStart(2,'0')}</span></div><div class="grid-3">${ms.map(memberCard).join('')}</div></section>`:'';}).join(''):'<div class="empty-state" role="status">No members match your search. Try another name, interest, or year.</div>';}
function profile(m){return `${pageHero('MEMBER PORTFOLIO','', '',`<div class="profile-hero">${avatar(m)}<div><h1>${esc(m.name)}</h1><p class="profile-role">${esc(m.designation)}</p><p class="profile-affiliation">${esc(m.affiliation)} · Member since ${esc(m.joined)}</p><div class="profile-links">${external('Google Scholar',m.scholar,'scholar')}${external('ResearchGate',m.researchgate,'external')}${external('LinkedIn',m.linkedin,'linkedin')}${m.website?external('Website',m.website,'globe'):''}<a href="mailto:${esc(m.email)}">${icon('mail',14)}Email</a></div></div></div>`,[{label:'Team',url:'/team'},{label:m.name}])}<section class="section container detail-layout"><div><section class="detail-section"><h2>About ${esc(m.name.replace(/^(Dr\.|Prof\.)\s*/, '').split(' ')[0])}</h2><p>${esc(m.bio)}</p><p>${esc(m.about)}</p></section><section class="detail-section"><h2>Research interests</h2><div class="chips">${m.interests.map(i=>`<span class="chip">${esc(i)}</span>`).join('')}</div></section><section class="detail-section"><h2>Selected publications</h2>${papers(m.publications)}</section><section class="detail-section"><h2>Research & projects</h2>${m.projects.length?`<div class="grid-2">${m.projects.map(project).filter(Boolean).map(projectCard).join('')}</div>`:'<p>Research projects will be shared here as this portfolio grows.</p>'}</section><section class="detail-section"><h2>Education</h2><ul class="list-clean">${m.education.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></section></div><aside><div class="side-card"><h3>Connect & collaborate</h3><p>Interested in ${esc(m.name.replace(/^(Dr\.|Prof\.)\s*/, '').split(' ')[0])}’s work? Get in touch to discuss research and learning opportunities.</p>${btn('Send an email','mailto:'+m.email,'secondary')}<dl><dt>Research group</dt><dd>${esc(m.group)}</dd><dt>Affiliation</dt><dd>${esc(m.affiliation)}</dd><dt>Joined</dt><dd>${esc(m.joined)}</dd></dl></div><div class="side-card">${arrowLink('Back to the team','/team')}</div></aside></section>`;}
function labs(){return `${pageHero('OUR VIRTUAL LABS','Virtual Research Labs','Explore the AI in Power System Lab and Applied Quantum Machine Learning Lab, including research projects, learning resources, and internship information.','',[{label:'Labs'}])}<section class="section container"><div class="grid-2">${D.labs.map(labCard).join('')}</div><div class="grid-3" style="margin-top:50px">${[{icon:'book',title:'Class recordings and notes',text:'Revisit class recordings, reading lists, and lecture notes whenever you need them.'},{icon:'compass',title:'Guided research internships',text:'Follow a structured 8-week pathway with mentoring, experiments, and a final project.'},{icon:'scholar',title:'Completion certificates',text:'Complete the learning modules and project review to meet the planned certificate requirements.'}].map(x=>`<div class="pillar"><div class="course-icon mint">${icon(x.icon,23)}</div><h3>${x.title}</h3><p>${x.text}</p></div>`).join('')}</div></section>`;}
function labDetail(l){return `${pageHero(l.category,l.title,l.summary,`<div class="buttons"><button class="btn" data-action="enroll" data-kind="lab" data-id="${esc(l.slug)}">Express interest ${icon('arrow',16)}</button><a class="btn secondary" href="#learning-resources">Explore resources ${icon('book',16)}</a></div>`,[{label:'Labs',url:'/labs'},{label:l.title}])}<section class="section container detail-layout"><div><section class="detail-section"><h2>Inside the lab</h2><p>${esc(l.description)}</p></section><section class="detail-section"><h2>Focus areas</h2><div class="chips">${l.focus.map(f=>`<span class="chip">${esc(f)}</span>`).join('')}</div></section><section class="detail-section" id="learning-resources"><div class="eyebrow">LEARNING RESOURCES</div><h2>Class recordings</h2>${videos(l.recordings)}</section><section class="detail-section"><h2>Papers & lecture notes</h2>${documents(l.documents)}</section><section class="detail-section"><h2>Related research</h2><div class="grid-2">${l.projects.map(project).filter(Boolean).map(projectCard).join('')}</div></section><section class="detail-section"><h2>Learning pathways</h2><div class="grid-2">${l.courses.map(course).filter(Boolean).map(c=>courseCard(c,true)).join('')}</div></section></div><aside><div class="side-card"><h3>Your lab mentors</h3>${l.members.map(member).map(miniMember).join('')}</div><div class="side-card mint"><h3>Research internship</h3><p>${esc(l.internship)}</p><h3>Certificate pathway</h3><p>${esc(l.certificate)}</p><button class="btn" data-action="enroll" data-kind="lab" data-id="${esc(l.slug)}">Express interest ${icon('arrow',16)}</button></div></aside></section>`;}
function courses(){return `${pageHero('LEARNING PATHWAYS','Courses','Practical, guided courses that connect foundational knowledge with the questions our labs explore.','',[{label:'Courses'}])}<section class="section container"><div class="toolbar"><div class="filter-group" data-filter-set="course-level">${['All courses','Beginner','Intermediate'].map((v,i)=>`<button class="filter-btn ${i?'':'active'}" aria-pressed="${!i}" data-filter-button="course-level" data-value="${i?v:'all'}">${v}</button>`).join('')}</div><input type="search" data-filter="course-search" aria-label="Search courses" placeholder="Find your next course…"></div><div class="grid-3 course-directory" id="course-results">${D.courses.map(c=>courseCard(c,true)).join('')}</div></section>`;}
function courseDetail(c){return `${pageHero(c.category,c.title,c.summary,`<div class="buttons"><span class="badge">${esc(c.level)}</span><span class="badge neutral">${esc(c.duration)} · Self-paced resources</span><span class="badge ${c.status==='Coming soon'?'neutral':''}">${esc(c.status)}</span></div>`,[{label:'Courses',url:'/courses'},{label:c.title}])}<section class="section container detail-layout"><div><section class="detail-section"><h2>About this course</h2><p>${esc(c.summary)}</p><p>Work through a guided series of concepts and practical exercises, and bring your questions to the lab community. Each module builds toward a small, documented experiment.</p></section><section class="detail-section"><h2>What you’ll explore</h2><ol class="syllabus list-clean">${c.modules.map(m=>`<li>${esc(m)}</li>`).join('')}</ol></section><section class="detail-section"><h2>Before you begin</h2><p>${esc(c.prerequisites)}</p></section><section class="detail-section"><h2>Lecture videos</h2>${videos(c.videos)}</section><section class="detail-section"><h2>Slides, notes & assignments</h2>${documents(c.documents)}</section></div><aside><div class="side-card"><h3>Your learning pathway</h3><dl><dt>Level</dt><dd>${esc(c.level)}</dd><dt>Duration</dt><dd>${esc(c.duration)}</dd><dt>Course status</dt><dd>${esc(c.status)}</dd></dl><p style="margin-top:20px">${c.status==='Coming soon'?'Join the interest list to hear when the course opens.':'Express interest in the next cohort and start exploring the learning resources.'}</p><button class="btn" data-action="enroll" data-kind="course" data-id="${esc(c.slug)}">${c.status==='Coming soon'?'Join interest list':'Express interest'} ${icon('arrow',16)}</button></div><div class="side-card"><h3>Meet your instructor</h3>${miniMember(member(c.instructor))}</div><div class="side-card mint"><h3>Learning with purpose</h3><p>Connect your coursework with a lab internship. Project completion and a review form part of the planned certificate pathway.</p>${arrowLink('Explore our labs','/labs')}</div></aside></section>`;}
function projects(){const funded=new URLSearchParams(location.search).get('filter')==='funded';return `${pageHero('RESEARCH IN MOTION','Research Projects','Explore our ongoing work in intelligent energy, secure systems, and applied quantum learning.','',[{label:'Projects'}])}<section class="section container"><div class="toolbar"><div class="filter-group" data-filter-set="project-category"><button class="filter-btn ${funded?'':'active'}" aria-pressed="${!funded}" data-filter-button="project-category" data-value="all">All projects</button><button class="filter-btn ${funded?'active':''}" aria-pressed="${funded}" data-filter-button="project-category" data-value="funded">Funded research projects</button>${D.labs.map(l=>`<button class="filter-btn" aria-pressed="false" data-filter-button="project-category" data-value="${esc(l.slug)}">${l.slug==='applied-qml'?'Applied Quantum ML':'AI in Power Systems'}</button>`).join('')}</div><input type="search" data-filter="project-search" aria-label="Search projects" placeholder="Search research topics…"></div><div class="grid-2" id="project-results">${D.projects.filter(p=>!funded||p.funded).map(projectCard).join('')}</div></section>`;}
const projectTabs=['Overview','Reference Papers','Explanation Videos','Code','Supporting Documents','Team'];
function projectDetail(p){return `${pageHero(p.category,p.title,p.summary,`<div class="buttons"><span class="badge">${esc(p.status)}</span>${p.funded?'<span class="badge lavender">Funded research</span>':''}<span class="badge neutral">${esc(p.period)}</span></div>`,[{label:'Projects',url:'/projects'},{label:p.title}])}<section class="section container detail-layout"><div><div class="project-art ${esc(p.color)}" style="height:260px;border-radius:22px;margin-bottom:35px">${projectArt(p)}</div><div class="tabs" role="tablist" aria-label="Project sections">${projectTabs.map((t,i)=>`<button class="tab" role="tab" id="project-tab-${i}" data-action="project-tab" data-id="${esc(p.slug)}" data-tab="${i}" aria-selected="${!i}" aria-controls="project-panel" tabindex="${i?-1:0}">${t}</button>`).join('')}</div><div id="project-panel" role="tabpanel" tabindex="0" aria-labelledby="project-tab-0">${projectPanel(p,0)}</div></div><aside><div class="side-card"><div class="eyebrow">TEAM LEADER</div>${miniMember(member(p.leader))}<p style="margin-top:15px">${esc(member(p.leader)?.bio)}</p>${arrowLink('View full portfolio',route('team',p.leader))}</div><div class="side-card"><h3>Project at a glance</h3><dl><dt>Research lab</dt><dd><a href="${route('labs',p.lab)}">${esc(lab(p.lab)?.title)} ↗</a></dd><dt>Status</dt><dd>${esc(p.status)}</dd><dt>Timeline</dt><dd>${esc(p.period)}</dd>${p.funded?`<dt>Funding source</dt><dd>${esc(p.funder)}</dd><dt>Grant reference</dt><dd>${esc(p.grant)}</dd>`:''}</dl><div class="chips" style="margin-top:20px">${p.keywords.map(k=>`<span class="chip">${esc(k)}</span>`).join('')}</div></div></aside></section>`;}
function projectPanel(p,i){return `<section class="detail-section">${[()=>`<h2>Project overview</h2><p>${esc(p.description)}</p><h3>Research objectives</h3><ul class="list-clean">${p.objectives.map(o=>`<li>${esc(o)}</li>`).join('')}</ul>`,()=>`<h2>Reference papers</h2>${papers(p.papers)}`,()=>`<h2>Explanation videos</h2>${videos(p.videos)}`,()=>`<h2>Code & reproducibility</h2>${safeUrl(p.code)?`<p>Explore the project repository for code, setup instructions, and reproducible experiments.</p>${external('View code repository',p.code,'github','btn secondary')}`:'<p>The project repository will be shared here when it is ready.</p>'}`,()=>`<h2>Supporting documents</h2>${documents(p.documents)}`,()=>`<h2>Meet the research team</h2><div class="grid-2">${p.members.map(member).filter(Boolean).map(memberCard).join('')}</div>`][i]()}</section>`;}
function papers(ids){const ps=(ids||[]).map(paper).filter(Boolean);return ps.length?ps.map(p=>`<article class="paper"><h3>${esc(p.title)}</h3><p>${esc(p.authors)}</p><p>${esc(p.venue)} · ${p.year}</p>${safeUrl(p.url)?external('Read paper / DOI',p.url,'external','text-link'):asset(p.pdf)?external('Read PDF',p.pdf,'download','text-link'):'<span class="coming">Paper link coming soon</span>'}</article>`).join(''):'<p>Publications will be listed here as the research progresses.</p>';}
function documents(ds){return ds?.length?ds.map(d=>`<div class="resource-row"><div><h4>${esc(d.title)}</h4><p>${esc(d.kind)}</p></div>${asset(d.url)?`<div class="buttons">${external('Preview',d.url,'external','text-link')}<a class="text-link" href="${esc(asset(d.url))}" download target="_blank" rel="noopener noreferrer">${icon('download',14)}Download</a></div>`:'<span class="coming">Available soon</span>'}</div>`).join(''):'<p>Supporting resources will be shared here when available.</p>';}
function videoPlayer(v){const u=asset(v.url);if(!u)return `<div class="video-empty">${icon('play',25)}Recording coming soon</div>`;try{const url=new URL(u);let src='';if(['www.youtube.com','youtube.com','m.youtube.com'].includes(url.hostname)){const id=url.searchParams.get('v')||url.pathname.split('/').at(-1);if(/^[a-zA-Z0-9_-]{11}$/.test(id))src='https://www.youtube-nocookie.com/embed/'+id;}if(url.hostname==='youtu.be'&&/^[a-zA-Z0-9_-]{11}$/.test(url.pathname.slice(1)))src='https://www.youtube-nocookie.com/embed/'+url.pathname.slice(1);if(['vimeo.com','www.vimeo.com'].includes(url.hostname)&&/^\d+$/.test(url.pathname.slice(1)))src='https://player.vimeo.com/video/'+url.pathname.slice(1);if(src)return `<iframe src="${src}" title="${esc(v.title)}" loading="lazy" allow="fullscreen; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`;if(/\.(mp4|webm|ogg)$/i.test(url.pathname))return `<video controls preload="none" aria-label="${esc(v.title)}" src="${esc(u)}"></video>`;return `<div class="video-empty">${external('Watch recording',u,'play','text-link')}</div>`;}catch{return '';}}
function videos(vs){return vs?.length?vs.map(v=>`<div class="resource-video">${videoPlayer(v)}<div class="video-caption">${v.session?`<span class="badge neutral" style="margin-right:10px">${esc(v.session)}</span>`:''}${esc(v.title)}</div></div>`).join(''):'<p>Explanation videos will be added as the project develops.</p>';}
function eventCard(e){const d=dateParts(e),up=new Date(e.end)>new Date();return `<article class="event-card"><div class="event-card-head">${dateBox(e)}<div class="event-time">${esc(d.date)}<br>${esc(d.time)} · ${esc(e.timezone)}</div></div><div class="event-card-content"><span class="badge ${up?'':'neutral'}">${up?'Upcoming':'Past session'}</span><h3><a href="${route('events',e.slug)}">${esc(e.title)}</a></h3><p>${esc(e.summary)}</p>${miniMember(member(e.speaker))}<div style="margin-top:20px">${arrowLink(up?'Event details & registration':'View session & resources',route('events',e.slug))}</div></div></article>`;}
function events(){return `${pageHero('CONVERSATIONS THAT CONNECT','Meet at the edge\nof what’s next.','Seminars, practical sessions, and shared conversations. Open your calendar to a new idea.','',[{label:'Events'}])}<section class="section container"><div class="toolbar"><div class="filter-group" data-filter-set="event-period">${['Upcoming','Past events','All events'].map((t,i)=>`<button class="filter-btn ${i?'':'active'}" data-filter-button="event-period" data-value="${['upcoming','past','all'][i]}" aria-pressed="${!i}">${t}</button>`).join('')}</div><label><span class="sr-only">Filter events by year</span><select class="select" data-filter="event-year"><option value="all">All years</option>${[...new Set(D.events.map(e=>new Date(e.date).getUTCFullYear()))].sort((a,b)=>b-a).map(y=>`<option>${y}</option>`).join('')}</select></label></div><div class="grid-2" id="event-results">${futureEvents().map(eventCard).join('')||'<div class="empty-state">New conversations are being planned. Explore past events while you wait.</div>'}</div></section>`;}
function eventDetail(e){const d=dateParts(e),up=new Date(e.end)>new Date();return `${pageHero(e.type,e.title,e.summary,`<div class="buttons"><span class="badge ${up?'':'neutral'}">${up?'Upcoming seminar':'Past event'}</span><span class="badge neutral">${esc(d.date)}</span></div>`,[{label:'Events',url:'/events'},{label:e.title}])}<section class="section container detail-layout"><div><section class="detail-section"><h2>About the conversation</h2><p>${esc(e.summary)}</p><p>This session brings our research community together for an accessible discussion, practical perspectives, and time for your questions.</p></section><section class="detail-section"><h2>Meet the speaker</h2>${memberCard(member(e.speaker))}</section><section class="detail-section"><h2>What’s on the agenda</h2><ol class="syllabus list-clean">${e.agenda.map(a=>`<li>${esc(a)}</li>`).join('')}</ol></section>${!up?`<section class="detail-section"><h2>Session report</h2><p>${esc(e.report||'A session summary will be shared here soon.')}</p></section><section class="detail-section"><h2>Recording & speaker slides</h2>${e.recording?videos([{title:e.title,url:e.recording}]):'<p>The recording will be shared here when available.</p>'}${documents([{title:'Speaker slides',kind:'Presentation · PDF',url:e.slides}])}</section><section class="detail-section"><h2>Past event gallery</h2>${e.photos?.length?`<div class="gallery">${e.photos.filter(p=>asset(typeof p==='string'?p:p.url)).map(p=>`<img src="${esc(asset(typeof p==='string'?p:p.url))}" alt="${esc(typeof p==='string'?'Event photograph':p.alt||'Event photograph')}" loading="lazy">`).join('')}</div>`:'<p>Event photos will appear here when the gallery is available.</p>'}</section>`:''}</div><aside><div class="side-card"><h3>Save your seat</h3><dl><dt>Date</dt><dd>${esc(d.date)}</dd><dt>Time</dt><dd>${esc(d.time)} · ${esc(e.timezone)}</dd><dt>Location</dt><dd>Online</dd><dt>Speaker</dt><dd>${esc(member(e.speaker)?.name)}</dd></dl>${up?`<button class="btn" style="margin-top:23px" data-action="register" data-id="${esc(e.slug)}">Register interest ${icon('arrow',16)}</button><div class="countdown" data-countdown="${esc(e.date)}">${countdown(e.date)}</div>`:'<p style="margin-top:20px">This session has ended. Explore our upcoming events to join the next conversation.</p>'}<button class="btn secondary" data-action="calendar" data-id="${esc(e.slug)}" style="margin-top:12px">${icon('calendar',15)}Add to calendar</button>${e.meetingUrl&&up?`<div style="margin-top:15px">${external('Join meeting',e.meetingUrl,'external','text-link')}</div>`:''}</div></aside></section>`;}
function countdown(v){const diff=new Date(v)-Date.now();if(diff<=0)return 'The session is starting or underway.';const days=Math.floor(diff/86400000),hours=Math.floor(diff/3600000)%24;return `${days} days · ${hours} hours to go`;}
function publications(){return `${pageHero('THE OPEN RESEARCH SHELF','Publications','Working papers, research preprints, and publications from across our projects.','',[{label:'Publications'}])}<section class="section container"><label for="paper-search" class="sr-only">Search publications</label><input id="paper-search" type="search" data-filter="paper-search" placeholder="Search a paper or author…" style="margin-bottom:35px"><div id="paper-results">${papers(D.publications.map(p=>p.id))}</div></section>`;}
function contact(){return `${pageHero('SAY HELLO','Contact the Lab','Ask about our research, learning opportunities, or ways to work together.','',[{label:'Contact'}])}<section class="section container grid-2"><div class="contact-info"><div class="eyebrow">OPEN FRONTIER LAB</div><h3>Let’s connect.</h3><p>${esc(D.organization.tagline)}</p><a href="mailto:${esc(D.organization.email)}">${esc(D.organization.email)}</a><p>${esc(D.organization.address)}</p><div class="social-links">${Object.entries(D.organization.social).map(([k,v])=>external(k[0].toUpperCase()+k.slice(1),v,k)).join('')}</div></div><form data-form="contact"><div class="form-grid">${field('name','Your name','text','name')}${field('email','Email address','email','email')}</div>${field('subject','Subject','text') }<div class="field"><label for="message">Your message</label><textarea id="message" name="message" required maxlength="5000"></textarea></div><button class="btn">${D.organization.contactEndpoint?'Send message':'Prepare email'}${icon('arrow',16)}</button><p class="form-note">${D.organization.contactEndpoint?'Your message will be sent to the lab.':'Opens your email app with a draft. Your message is sent only when you send it from your email app.'}</p><p class="form-feedback" role="status"></p></form></section>`;}
function readLocal(){try{const rows=JSON.parse(localStorage.getItem('ofl-v1-registrations')||'[]');return Array.isArray(rows)?rows:[];}catch{return [];}}
function saveLocal(record){try{const rows=readLocal();rows.push({...record,createdAt:new Date().toISOString()});localStorage.setItem('ofl-v1-registrations',JSON.stringify(rows));return true;}catch{return false;}}
function registrations(){const rows=readLocal().filter(r=>r.kind!=='newsletter');return `${pageHero('SAVED REGISTRATIONS','My registrations','Review the interests you have saved on this device. Demo records do not reserve a seat or send an email.','',[{label:'My registrations'}])}<section class="section container"><div class="toolbar"><p class="small">${rows.length} saved ${rows.length===1?'registration':'registrations'}</p><div class="buttons"><button class="btn secondary small-btn" data-action="export">${icon('download',15)}Export CSV</button>${rows.length?'<button class="btn secondary small-btn" data-action="clear-registrations">Clear device records</button>':''}</div></div>${rows.length?rows.map(r=>`<div class="resource-row"><div><h4>${esc(r.title)}</h4><p>${esc(r.name)} · ${esc(r.email)} · ${shortDate(r.createdAt)}</p></div><span class="badge neutral">${esc(r.delivery==='submitted'?'Submitted':'Device only')}</span></div>`).join(''):'<div class="empty-state">No interests saved yet. <a href="/events" class="text-link">Explore upcoming events ↗</a></div>'}<p class="notice">These records belong to this browser. A shared attendee dashboard and automatic confirmation emails require a connected registration service.</p></section>`;}
function notFound(){return `${pageHero('404','Page not found','This page does not exist. Explore our research, meet the team, or return to the lab.',`<div class="buttons">${btn('Back to home','/')}${btn('Explore the labs','/labs','secondary')}</div>`,[{label:'Page not found'}])}`;}
function field(name,label,type='text',autocomplete=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" type="${type}" name="${name}" required maxlength="${type==='email'?254:150}" ${autocomplete?`autocomplete="${autocomplete}"`:''}></div>`;}
function showDialog(title,body){dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-btn" data-action="close-dialog" aria-label="Close dialog">${icon('close',21)}</button></div>${body}`;dialog.showModal();}
function openRegistration(kind,id,itemType=''){const item=kind==='event'?D.events.find(e=>e.slug===id):itemType==='lab'?lab(id):course(id);if(!item)return;const endpoint=kind==='event'?D.organization.registrationEndpoint:D.organization.enrollmentEndpoint;showDialog(kind==='event'?'Event registration':'Lab and course enrollment',`<p class="dialog-description">${esc(item.title)}</p><form data-form="registration" data-kind="${kind}" data-item-type="${itemType}" data-id="${esc(id)}"><div class="form-grid">${field('name','Full name','text','name')}${field('email','Email address','email','email')}${field('affiliation','Affiliation / institution','text','organization')}${field('country','Country','text','country-name')}</div><p class="form-note">${endpoint?'Your details will be submitted to our registration service. Confirmation and meeting details are managed by the organizer.':'V1 demo: this saves your interest on this device only. It does not send a confirmation email, reserve a place, or enroll you in a course. The organizer will add the registration service later.'}</p><button class="btn" type="submit">${endpoint?'Submit registration':'Save my interest'} ${icon('arrow',16)}</button><p class="form-feedback" role="status"></p></form>`);}
function openSearch(){showDialog('Search the lab',`<label for="site-search" class="sr-only">Search projects, people, courses, labs, papers and events</label><input class="search-input" type="search" id="site-search" placeholder="Search people, projects, papers…" autocomplete="off"><div id="search-results" aria-live="polite"><p class="small">Explore the research, people, and learning pathways across the lab.</p></div>`);}
function searchResults(q){const all=[...D.members.map(m=>({title:m.name,detail:[m.designation,...m.interests].join(' '),type:'Team portfolio',url:route('team',m.slug)})),...D.projects.map(p=>({title:p.title,detail:[p.summary,...p.keywords].join(' '),type:'Research project',url:route('projects',p.slug)})),...D.courses.map(c=>({title:c.title,detail:c.summary,type:'Course',url:route('courses',c.slug)})),...D.labs.map(l=>({title:l.title,detail:l.summary,type:'Virtual lab',url:route('labs',l.slug)})),...D.publications.map(p=>({title:p.title,detail:p.authors,type:'Publication',url:'/publications?q='+encodeURIComponent(p.title)})),...D.events.map(e=>({title:e.title,detail:e.summary,type:'Event',url:route('events',e.slug)}))];const needle=q.trim().toLowerCase();if(!needle)return '<p class="small">Try “quantum”, “forecasting”, or a researcher’s name.</p>';const found=all.filter(r=>(r.title+' '+r.detail).toLowerCase().includes(needle)).slice(0,15);return found.length?found.map(r=>`<a class="search-result" href="${esc(r.url)}"><span><small>${r.type}</small><b>${esc(r.title)}</b></span>${icon('arrow',16)}</a>`).join(''):'<div class="empty-state">No matches yet. Try a broader research topic.</div>';}
function render(focus=false){const parts=location.pathname.replace(/\/$/,'').split('/').filter(Boolean);if(document.documentElement)document.documentElement.dataset.page=parts.length?'inner':'home';let html,title;if(!parts.length){html=home();title='Virtual Research Lab';}else if(parts.length===1){const pages={about,team,labs,courses,projects,events,publications,contact,registrations};html=pages[parts[0]]?.();title=parts[0][0].toUpperCase()+parts[0].slice(1);}else if(parts.length===2){const pairs={team:[D.members,profile],labs:[D.labs,labDetail],courses:[D.courses,courseDetail],projects:[D.projects,projectDetail],events:[D.events,eventDetail]};const pair=pairs[parts[0]];const item=pair?.[0].find(i=>i.slug===parts[1]);if(item){html=pair[1](item);title=item.name||item.title;}}
  main.innerHTML=html||notFound();document.title=`${title||'Page not found'} | ${D.organization.name}`;const desc=main.querySelector('.page-hero p,.cs-hero-description')?.textContent||D.organization.description;document.querySelector('meta[name=description]').setAttribute('content',desc);document.querySelector('meta[property="og:title"]').setAttribute('content',document.title);document.querySelector('meta[property="og:description"]').setAttribute('content',desc);document.querySelector('link[rel=canonical]')?.setAttribute('href',location.origin+location.pathname);document.querySelector('meta[property="og:url"]')?.setAttribute('content',location.origin+location.pathname);header();footer();enhancePage();if(focus){main.focus({preventScroll:true});window.scrollTo(0,0);updateScrollChrome();}const query=new URLSearchParams(location.search).get('q');if(parts[0]==='publications'&&query){document.querySelector('#paper-search').value=query;applyFilters();}if(location.hash){requestAnimationFrame(()=>document.getElementById(decodeURIComponent(location.hash.slice(1)))?.scrollIntoView());}}
function navigate(url){if(dialog.open)dialog.close();history.pushState({},'',url);render(true);}
function activeFilter(name){return document.querySelector(`[data-filter-button="${name}"].active`)?.dataset.value||'all';}
function applyFilters(){const teamOut=document.querySelector('#team-results');if(teamOut)teamOut.innerHTML=teamResults();const pOut=document.querySelector('#project-results');if(pOut){const f=activeFilter('project-category'),q=document.querySelector('[data-filter=project-search]').value.toLowerCase();const ps=D.projects.filter(p=>(f==='all'||(f==='funded'?p.funded:p.lab===f))&&[p.title,p.summary,...p.keywords].join(' ').toLowerCase().includes(q));pOut.innerHTML=ps.map(projectCard).join('')||'<div class="empty-state" role="status">No projects match these filters.</div>';}
  const cOut=document.querySelector('#course-results');if(cOut){const f=activeFilter('course-level'),q=document.querySelector('[data-filter=course-search]').value.toLowerCase();cOut.innerHTML=D.courses.filter(c=>(f==='all'||c.level===f)&&(c.title+' '+c.summary).toLowerCase().includes(q)).map(c=>courseCard(c,true)).join('')||'<div class="empty-state" role="status">No courses match these filters.</div>';}
  const eOut=document.querySelector('#event-results');if(eOut){const f=activeFilter('event-period'),y=document.querySelector('[data-filter=event-year]').value;const es=D.events.filter(e=>(f==='all'||(f==='upcoming'?new Date(e.end)>new Date():new Date(e.end)<=new Date()))&&(y==='all'||String(new Date(e.date).getUTCFullYear())===y)).sort((a,b)=>f==='past'?new Date(b.date)-new Date(a.date):new Date(a.date)-new Date(b.date));eOut.innerHTML=es.map(eventCard).join('')||'<div class="empty-state" role="status">No events in this view. Try another year or explore past sessions.</div>';}
  const paperOut=document.querySelector('#paper-results');if(paperOut){const q=document.querySelector('#paper-search').value.toLowerCase();paperOut.innerHTML=papers(D.publications.filter(p=>[p.title,p.authors,p.venue,p.year].join(' ').toLowerCase().includes(q)).map(p=>p.id));}}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),4000);}
function download(filename,body,type){const u=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function calendar(e){const time=d=>new Date(d).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const ie=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const text=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Open Frontier Lab//Events//EN','CALSCALE:GREGORIAN','BEGIN:VEVENT',`UID:${e.slug}@open-frontier-lab.example`,`DTSTAMP:${time(new Date())}`,`DTSTART:${time(e.date)}`,`DTEND:${time(e.end)}`,`SUMMARY:${ie(e.title)}`,`DESCRIPTION:${ie(e.summary+'\nTimezone: '+e.timezone+'\n'+location.origin+route('events',e.slug))}`,'LOCATION:Online','END:VEVENT','END:VCALENDAR',''].join('\r\n');download(e.slug+'.ics',text,'text/calendar;charset=utf-8');toast('Calendar file downloaded. Open it in your calendar app.');}
function exportRecords(){const rows=readLocal().filter(r=>r.kind!=='newsletter');if(!rows.length){toast('No registrations to export yet.');return;}const keys=['kind','title','name','email','affiliation','country','createdAt','delivery'];const cell=v=>'"'+String(v??'').replace(/^[=+\-@]/,"'$&").replace(/"/g,'""')+'"';download('open-frontier-registrations.csv','\uFEFF'+[keys.map(cell).join(','),...rows.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n'),'text/csv;charset=utf-8');}
document.addEventListener('click',ev=>{const a=ev.target.closest('a');if(a&&!ev.metaKey&&!ev.ctrlKey&&!ev.shiftKey&&!ev.altKey&&ev.button===0&&!a.target&&!a.hasAttribute('download')){const u=new URL(a.href);if(u.origin===location.origin){if(u.pathname===location.pathname&&u.search===location.search&&u.hash){if(dialog.open)dialog.close();document.querySelector('.nav-links')?.classList.remove('open');document.querySelector('[data-action=menu]')?.setAttribute('aria-expanded','false');return;}ev.preventDefault();navigate(u.pathname+u.search+u.hash);return;}}
  const filter=ev.target.closest('[data-filter-button]');if(filter){document.querySelectorAll(`[data-filter-button="${filter.dataset.filterButton}"]`).forEach(b=>{b.classList.toggle('active',b===filter);b.setAttribute('aria-pressed',String(b===filter));});if(filter.dataset.filterButton==='project-category'){const u=new URL(location.href);if(filter.dataset.value==='funded')u.searchParams.set('filter','funded');else u.searchParams.delete('filter');history.replaceState({},'',u);}applyFilters();return;}
  const b=ev.target.closest('[data-action]');if(!b)return;switch(b.dataset.action){case 'menu':{const nav=document.querySelector('.nav-links');nav.classList.toggle('open');b.setAttribute('aria-expanded',String(nav.classList.contains('open')));break;}case 'registration-info':openRegistrationNotice();break;case 'search':openSearch();break;case 'close-dialog':dialog.close();break;case 'register':openRegistration('event',b.dataset.id);break;case 'enroll':openRegistration('enrollment',b.dataset.id,b.dataset.kind);break;case 'calendar':calendar(D.events.find(e=>e.slug===b.dataset.id));break;case 'project-tab':{const i=Number(b.dataset.tab);document.querySelectorAll('.tab').forEach(t=>{t.setAttribute('aria-selected',String(t===b));t.tabIndex=t===b?0:-1;});const panel=document.querySelector('#project-panel');panel.innerHTML=projectPanel(project(b.dataset.id),i);panel.setAttribute('aria-labelledby',b.id);break;}case 'export':exportRecords();break;case 'clear-registrations':showDialog('Clear saved registrations?',`<p class="dialog-description">This removes the interests saved in this browser. You can export a CSV first to keep a copy.</p><div class="buttons"><button class="btn secondary" data-action="close-dialog">Keep records</button><button class="btn" data-action="confirm-clear">Clear records</button></div>`);break;case 'confirm-clear':try{localStorage.removeItem('ofl-v1-registrations');dialog.close();render();toast('Device records cleared.');}catch{toast('This browser could not clear the records.');}break;}});
document.addEventListener('input',ev=>{if(ev.target.id==='site-search')document.querySelector('#search-results').innerHTML=searchResults(ev.target.value);else if(ev.target.matches('[data-filter]'))applyFilters();});
document.addEventListener('change',ev=>{if(ev.target.matches('[data-filter]'))applyFilters();});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){document.querySelector('.nav-links')?.classList.remove('open');document.querySelector('[data-action=menu]')?.setAttribute('aria-expanded','false');}if(ev.target.matches('.tab')&&['ArrowLeft','ArrowRight','Home','End'].includes(ev.key)){ev.preventDefault();const tabs=[...document.querySelectorAll('.tab')],i=tabs.indexOf(ev.target);const next=ev.key==='Home'?0:ev.key==='End'?tabs.length-1:(i+(ev.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();tabs[next].focus();}});
dialog.addEventListener('click',ev=>{if(ev.target===dialog){const rect=dialog.getBoundingClientRect();if(ev.clientX<rect.left||ev.clientX>rect.right||ev.clientY<rect.top||ev.clientY>rect.bottom)dialog.close();}});
async function submitEndpoint(endpoint,data){const url=safeUrl(endpoint);if(!url||!url.startsWith('https://'))throw new Error('The submission service is not configured correctly. Please contact the lab.');const res=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(data)});if(!res.ok)throw new Error('The service could not accept your submission. Please try again.');}
document.addEventListener('submit',async ev=>{const form=ev.target.closest('form[data-form]');if(!form)return;ev.preventDefault();if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));const feedback=form.querySelector('.form-feedback');const submit=form.querySelector('button[type=submit],button:not([type])');if(submit)submit.disabled=true;try{switch(form.dataset.form){case 'registration':{const kind=form.dataset.kind,item=kind==='event'?D.events.find(e=>e.slug===form.dataset.id):form.dataset.itemType==='lab'?lab(form.dataset.id):course(form.dataset.id);const endpoint=kind==='event'?D.organization.registrationEndpoint:D.organization.enrollmentEndpoint;const record={...values,kind,itemType:form.dataset.itemType,itemId:item.slug,title:item.title,delivery:endpoint?'submitted':'device only'};if(endpoint)await submitEndpoint(endpoint,record);const saved=saveLocal(record);if(!saved&&!endpoint)throw new Error('Your browser could not save the registration. Please enable local storage or contact the lab.');showDialog(endpoint?'Registration submitted':'Your interest is saved',`<p class="dialog-description">${esc(item.title)}</p><p class="small">${endpoint?'Your details were submitted to the registration service. The organizer manages confirmation and meeting details.':`Thanks, ${esc(values.name.split(' ')[0])}. Your interest is saved in this browser. No confirmation email has been sent, and this demo does not reserve a seat.`}</p><div class="buttons" style="margin-top:24px">${btn('View my registrations','/registrations')}${kind==='event'?`<button class="btn secondary" data-action="calendar" data-id="${esc(item.slug)}">${icon('calendar',16)}Add to calendar</button>`:''}</div>`);break;}
case 'newsletter':if(D.organization.newsletterEndpoint){await submitEndpoint(D.organization.newsletterEndpoint,values);toast('Your newsletter request has been submitted.');}else{if(!saveLocal({...values,kind:'newsletter',title:'Newsletter interest',delivery:'device only'}))throw new Error('Your browser could not save your interest.');toast('Newsletter interest saved on this device.');}form.reset();break;
case 'contact':if(D.organization.contactEndpoint){await submitEndpoint(D.organization.contactEndpoint,values);feedback.textContent='Your message has been submitted.';form.reset();}else{const body=`Name: ${values.name}\nEmail: ${values.email}\n\n${values.message}`;location.href=`mailto:${encodeURIComponent(D.organization.email)}?subject=${encodeURIComponent(values.subject)}&body=${encodeURIComponent(body)}`;feedback.textContent='Your email draft is ready. Send it from your email app.';}break;}}catch(err){if(feedback)feedback.textContent=err.message;else toast(err.message);}finally{if(submit)submit.disabled=false;}});
window.addEventListener('popstate',()=>{if(dialog.open)dialog.close();render(true);});
let revealObserver,statObserver,scrollFrame=0;
function updateScrollChrome(){const root=document.documentElement;if(!root)return;document.querySelector('#header')?.classList.toggle('is-scrolled',(window.scrollY||0)>12);const progress=document.querySelector('.scroll-progress');if(progress){const available=root.scrollHeight-window.innerHeight;progress.style.width=(available>0?Math.min(100,Math.max(0,(window.scrollY||0)/available*100)):0)+'%';}}
function enhancePage(){updateScrollChrome();revealObserver?.disconnect();statObserver?.disconnect();if(typeof IntersectionObserver!=='function'||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;
  const nodes=main.querySelectorAll('.home-heading,.home-focus,.home-project,.home-publication,.home-introduction>div,.home-contact-inner,.section-head,.intro>div,.lab-card,.project-card,.course-card,.member-card,.pillar,.event-banner,.news-row,.join-strip,.detail-section,.side-card,.partner');
  revealObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){entry.target.classList.remove('reveal-pending');revealObserver.unobserve(entry.target);}}},{rootMargin:'0px 0px -35px',threshold:.06});
  for(const node of nodes){node.classList.add('reveal-item','reveal-pending');revealObserver.observe(node);}
  statObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;statObserver.unobserve(entry.target);const final=entry.target.dataset.finalValue;const match=final.match(/^(\d+)(\+?)$/);if(!match)continue;const value=Number(match[1]),start=performance.now();const animate=now=>{if(!entry.target.isConnected)return;const progress=Math.min(1,(now-start)/1100);const display=Math.round(value*(1-Math.pow(1-progress,3)));entry.target.textContent=(progress===1?match[1]:String(display).padStart(match[1].length,'0'))+match[2];if(progress<1)requestAnimationFrame(animate);};requestAnimationFrame(animate);}},{threshold:.6});
  for(const node of main.querySelectorAll('.stat strong')){node.dataset.finalValue=node.textContent;statObserver.observe(node);}
}
function scheduleScrollChrome(){if(scrollFrame)return;scrollFrame=requestAnimationFrame(()=>{scrollFrame=0;updateScrollChrome();});}
window.addEventListener('scroll',scheduleScrollChrome,{passive:true});
window.addEventListener('resize',scheduleScrollChrome);
initializeAppearance();
setInterval(()=>document.querySelectorAll('[data-countdown]').forEach(el=>el.textContent=countdown(el.dataset.countdown)),60000);
try{const res=await fetch('/content.json');if(!res.ok)throw new Error('Content unavailable');D=await res.json();header();footer();render();}catch(err){main.innerHTML=`<section class="container section"><h1>The lab is taking a moment.</h1><p style="margin-top:20px">We couldn’t load the page content. Please refresh to try again.</p><button class="btn" style="margin-top:20px" onclick="location.reload()">Refresh page</button></section>`;console.error(err);}
